        a1: { title: "Article 1 : Purpose", text: "Asexcel provides a suite of online tools for processing Excel files and similar formats (cleaning, conversion, comparison, merging, splitting, formula translation, password protection), as well as an AI assistant able to generate and explain formulas in plain language. These Terms define the conditions of access to and use of these services." },
