        a5: { title: "Article 5 : AI quota and free features", text: "The AI assistant and formula generator are subject to a daily quota of free credits, the volume of which may vary depending on the User's status (guest, member). This quota, as well as the free availability of tools, may change at any time without notice, particularly in the event of technical or economic constraints." },
        aSub: { title: "Article 5 bis : Pro Subscription, Billing and Cancellation", text: "The Pro plan is offered as a monthly or annual auto-renewing subscription, billed through our payment provider Tebex. The subscription is commitment-free: the User may cancel at any time from the /compte page, with cancellation taking effect at the end of the period already paid for, with no pro-rata refund unless required by law. Prices shown on the /tarifs page may change; any change will apply starting from the next renewal, after prior notice to the User." },
