        a8: { title: "Article 8 : Personal data", text: "The processing of personal data carried out as part of the Service is described in detail in our {confidentialite}, which forms an integral part of these Terms. This policy specifies in particular the purposes of processing, retention periods, and the rights available to the User under the General Data Protection Regulation (GDPR)." },
        a9: { title: "Article 9 : Changes to the Service and Terms", text: "Asexcel may change, suspend, or modify all or part of the Service at any time, particularly for technical, legal, or security reasons. These Terms may also be amended; the last-updated date appears at the top of this page. In the event of a substantial change, notice will be provided via the Service." },
