        a7: { title: "Artículo 7 : Resolución", text: "El Usuario puede dejar de usar el Servicio y eliminar su cuenta en cualquier momento desde la página de Soporte. Asexcel se reserva el derecho de suspender o resolver el acceso de un Usuario en caso de incumplimiento grave o reiterado de estos Términos, previa notificación cuando sea razonablemente posible." },
        a8: { title: "Artículo 8 : Datos personales", text: "El tratamiento de datos personales realizado en el marco del Servicio se describe en detalle en nuestra {confidentialite}, que forma parte integrante de estos Términos. Esta política precisa en particular las finalidades del tratamiento, los plazos de conservación y los derechos de los que dispone el Usuario en virtud del Reglamento General de Protección de Datos (RGPD)." },
        a9: { title: "Artículo 9 : Evolución del Servicio y de los Términos", text: "Asexcel puede modificar, suspender o cambiar total o parcialmente el Servicio en cualquier momento, en particular por razones técnicas, legales o de seguridad. Estos Términos también pueden modificarse; la fecha de última actualización aparece en la parte superior de esta página. En caso de modificación sustancial, se proporcionará información a través del Servicio." },
        a10: { title: "Artículo 10 : Ley aplicable y contacto", text: "Estos Términos están sujetos a la ley aplicable en el lugar de establecimiento de Asexcel. Para cualquier pregunta relativa a estos términos, contáctanos a través de la página de {support}." },
