        badges: ["Recluta en Formación", "Mente Ágil", "Estratega Táctico", "Cerebro Cuántico", "Lógica de Hierro"],
        questions: {
          "logique-1": { prompt: "Pedro es más alto que Marcos. Marcos es más alto que Julia. ¿Quién es el más bajo de los tres?", options: ["Pedro", "Marcos", "Julia", "Imposible saberlo"], explanation: "Pedro > Marcos > Julia: Julia es, por tanto, la más baja de los tres." },
          "logique-2": { prompt: "Todos los X son Y. Algunos Y son Z. ¿Podemos afirmar con certeza que todos los X son Z?", options: ["Sí, con certeza", "No, no se puede afirmar"], explanation: "Solo algunos Y son Z: nada garantiza que los X (que son Y) estén entre ellos." },
          "logique-3": { prompt: "Si hoy es miércoles, ¿qué día será dentro de 100 días?", options: ["Jueves", "Viernes", "Sábado", "Domingo"], explanation: "100 = 14×7 + 2: avanzamos 2 días en el ciclo, miércoles + 2 = viernes." },
          "logique-4": { prompt: "Alicia siempre miente, Roberto siempre dice la verdad. Alicia afirma: «Roberto miente». ¿Qué se puede deducir?", options: ["Roberto dice la verdad", "Roberto miente", "Alicia dice la verdad", "Imposible saberlo"], explanation: "Alicia siempre miente, así que su afirmación «Roberto miente» es falsa: Roberto dice la verdad." },
          "logique-5": { prompt: "Un granjero cuenta 10 cabezas y 32 patas entre sus gallinas y conejos. ¿Cuántos conejos tiene?", options: ["4", "5", "6", "7"], explanation: "Con g gallinas y c conejos: g+c=10 y 2g+4c=32, lo que da c=6 y g=4." },
          "logique-6": { prompt: "¿Qué día viene después de esta secuencia: martes, jueves, sábado, …?", options: ["Domingo", "Lunes", "Martes", "Miércoles"], explanation: "La secuencia avanza 2 días cada vez: sábado + 2 días = lunes." },
          "suite-1": { prompt: "Completa la secuencia: 2, 4, 8, 16, ?", options: ["24", "30", "32", "36"], explanation: "Cada número se multiplica por 2: 16 × 2 = 32." },
          "suite-2": { prompt: "Completa la secuencia: 1, 1, 2, 3, 5, 8, ?", options: ["11", "12", "13", "15"], explanation: "Secuencia de Fibonacci: cada término es la suma de los dos anteriores. 5 + 8 = 13." },
          "suite-3": { prompt: "Completa la secuencia: 3, 6, 11, 18, 27, ?", options: ["36", "38", "40", "42"], explanation: "Las diferencias aumentan de 2 en 2 (+3, +5, +7, +9, +11): 27 + 11 = 38." },
          "suite-4": { prompt: "Completa la secuencia: 1, 4, 9, 16, 25, ?", options: ["30", "34", "36", "42"], explanation: "Son los cuadrados sucesivos (1², 2², 3²...): 6² = 36." },
          "suite-5": { prompt: "Completa la secuencia: 2, 6, 18, 54, ?", options: ["108", "144", "162", "180"], explanation: "Cada número se multiplica por 3: 54 × 3 = 162." },
          "suite-6": { prompt: "Completa la secuencia: 1, 3, 6, 10, 15, ?", options: ["18", "20", "21", "24"], explanation: "Números triangulares: se suma 2, luego 3, luego 4, luego 5, luego 6: 15 + 6 = 21." },
          "matrice-1": { prompt: "Completa la siguiente matriz respetando la lógica de sus filas y columnas.", options: ["● ● ●", "● ● ● ●", "● ● ● ● ●", "● ● ● ● ● ●"], explanation: "El número de puntos de una celda = (número de fila + número de columna − 1): 3 + 3 − 1 = 5." },
          "matrice-2": { prompt: "Completa la siguiente matriz respetando la lógica de sus filas y columnas.", options: ["△", "□", "○", "◇"], explanation: "Cada fila es un desplazamiento circular de la anterior: la 3ª casilla de la fila 3 es □." },
          "matrice-3": { prompt: "Completa la siguiente matriz respetando la lógica de sus filas y columnas.", options: ["17", "18", "19", "20"], explanation: "Los números aumentan de 2 en 2 leyendo la cuadrícula fila por fila: 16 + 2 = 18." },
          "matrice-4": { prompt: "Completa la siguiente matriz respetando la lógica de sus filas y columnas.", options: ["7", "8", "9", "10"], explanation: "Cada casilla equivale al número de fila multiplicado por el número de columna: 3 × 3 = 9." },
          "matrice-5": { prompt: "Completa la siguiente matriz respetando la lógica de sus filas y columnas.", options: ["12", "14", "16", "18"], explanation: "Cada casilla duplica la anterior, tanto en filas como en columnas: 8 × 2 = 16." },
          "matrice-6": { prompt: "Completa la siguiente matriz respetando la lógica de sus filas y columnas.", options: ["2", "3", "4", "5"], explanation: "Cada fila decrece de 2 en 2 y empieza 1 menos que la anterior: 5 − 2 = 3." },
          "intrus-1": { prompt: "Encuentra el intruso en esta lista: Perro, Gato, Pez, Mesa.", options: ["Perro", "Gato", "Pez", "Mesa"], explanation: "Perro, Gato y Pez son animales; Mesa es un objeto, es el intruso." },
          "intrus-2": { prompt: "Encuentra el intruso en esta lista: Rojo, Azul, Verde, Lunes.", options: ["Rojo", "Azul", "Verde", "Lunes"], explanation: "Rojo, Azul y Verde son colores; Lunes es un día de la semana, es el intruso." },
          "intrus-3": { prompt: "Encuentra el intruso en esta lista: Manzana, Plátano, Zanahoria, Pera.", options: ["Manzana", "Plátano", "Zanahoria", "Pera"], explanation: "Manzana, Plátano y Pera son frutas; Zanahoria es una verdura, es el intruso." },
          "intrus-4": { prompt: "Encuentra el intruso en esta lista: León, Tigre, Águila, Leopardo.", options: ["León", "Tigre", "Águila", "Leopardo"], explanation: "León, Tigre y Leopardo son felinos; Águila es un ave, es el intruso." },
          "intrus-5": { prompt: "Encuentra el intruso en esta lista: París, Londres, Tokio, Europa.", options: ["París", "Londres", "Tokio", "Europa"], explanation: "París, Londres y Tokio son ciudades; Europa es un continente, es el intruso." },
          "intrus-6": { prompt: "Encuentra el intruso entre estos números: 4, 9, 16, 20.", options: ["4", "9", "16", "20"], explanation: "4, 9 y 16 son cuadrados perfectos (2², 3², 4²); 20 no lo es, es el intruso." },
          "enigme-1": { prompt: "¿Qué símbolo completa la secuencia: ○ ● ○ ● ○ ?", options: ["○", "●", "◐", "◻"], explanation: "La secuencia alterna estrictamente ○ y ●: después de ○ siempre viene ●." },
          "enigme-2": { prompt: "¿Qué símbolo completa la secuencia: △ ▽ △ ▽ △ ?", options: ["△", "▽", "◇", "○"], explanation: "La secuencia alterna estrictamente △ y ▽: después de △ siempre viene ▽." },
          "enigme-3": { prompt: "Un triángulo se divide en 4 triángulos pequeños iguales trazando sus tres medianas. ¿Cuántos triángulos se ven en total (pequeños + grande combinados)?", options: ["4", "5", "6", "7"], explanation: "Se cuentan los 4 triángulos pequeños, más el triángulo grande original: 4 + 1 = 5." },
          "enigme-4": { prompt: "Un reloj marca las 3:15. ¿Cuál es el ángulo aproximado entre la aguja de las horas y la de los minutos?", options: ["0°", "7,5°", "15°", "30°"], explanation: "A las 3:15, la aguja de las horas está en 97,5° y la de los minutos en 90°: la diferencia es de unos 7,5°." },
          "enigme-5": { prompt: "Un cubo se pinta de rojo en todas sus caras y luego se corta en 27 cubos pequeños idénticos (3×3×3). ¿Cuántos cubos pequeños no tienen NINGUNA cara pintada?", options: ["0", "1", "6", "8"], explanation: "Solo el cubo pequeño situado exactamente en el centro no tiene ninguna cara pintada: la respuesta es 1." },
          "enigme-6": { prompt: "En una cuadrícula cuadrada de 3×3 casillas, ¿cuántos cuadrados se cuentan en total (de todos los tamaños)?", options: ["9", "12", "14", "16"], explanation: "9 cuadrados de 1×1, 4 cuadrados de 2×2 y 1 cuadrado de 3×3: 9 + 4 + 1 = 14." },
        },
