          "suite-3": { prompt: "أكمل التسلسل: 3، 6، 11، 18، 27، ؟", options: ["36", "38", "40", "42"], explanation: "الفروق تزداد بمقدار 2 في كل مرة (+3، +5، +7، +9، +11): 27 + 11 = 38." },
          "suite-4": { prompt: "أكمل التسلسل: 1، 4، 9، 16، 25، ؟", options: ["30", "34", "36", "42"], explanation: "هذه مربعات متتالية (1²، 2²، 3²...): 6² = 36." },
          "suite-5": { prompt: "أكمل التسلسل: 2، 6، 18، 54، ؟", options: ["108", "144", "162", "180"], explanation: "كل رقم يُضرب في 3: 54 × 3 = 162." },
