          "matrice-1": { prompt: "أكمل المصفوفة التالية باحترام منطق صفوفها وأعمدتها.", options: ["● ● ●", "● ● ● ●", "● ● ● ● ●", "● ● ● ● ● ●"], explanation: "عدد النقاط في الخلية = (رقم الصف + رقم العمود − 1): 3 + 3 − 1 = 5." },
