          "intrus-3": { prompt: "جد العنصر الدخيل في هذه القائمة: تفاحة، موزة، جزرة، كمثرى.", options: ["تفاحة", "موزة", "جزرة", "كمثرى"], explanation: "تفاحة وموزة وكمثرى فواكه؛ جزرة خضار، وهي الدخيل." },
