          "intrus-5": { prompt: "جد العنصر الدخيل في هذه القائمة: باريس، لندن، طوكيو، أوروبا.", options: ["باريس", "لندن", "طوكيو", "أوروبا"], explanation: "باريس ولندن وطوكيو مدن؛ أوروبا قارة، وهي الدخيل." },
