        badges: ["Recluta in Addestramento", "Mente Vivace", "Stratega Tattico", "Cervello Quantico", "Logica di Ferro"],
        questions: {
          "logique-1": { prompt: "Pierre è più alto di Marco. Marco è più alto di Giulia. Chi è il più basso dei tre?", options: ["Pierre", "Marco", "Giulia", "Impossibile dirlo"], explanation: "Pierre > Marco > Giulia: Giulia è quindi la più bassa dei tre." },
          "logique-2": { prompt: "Tutti gli X sono Y. Alcuni Y sono Z. Possiamo affermare con certezza che tutti gli X sono Z?", options: ["Sì, con certezza", "No, non si può affermare"], explanation: "Solo alcuni Y sono Z: nulla garantisce che gli X (che sono Y) ne facciano parte." },
          "logique-3": { prompt: "Se oggi è mercoledì, che giorno sarà tra 100 giorni?", options: ["Giovedì", "Venerdì", "Sabato", "Domenica"], explanation: "100 = 14×7 + 2: si avanza di 2 giorni nel ciclo, mercoledì + 2 = venerdì." },
          "logique-4": { prompt: "Alice mente sempre, Bob dice sempre la verità. Alice afferma: «Bob mente». Cosa si può dedurre?", options: ["Bob dice la verità", "Bob mente", "Alice dice la verità", "Impossibile dirlo"], explanation: "Alice mente sempre, quindi la sua affermazione «Bob mente» è falsa: Bob dice la verità." },
          "logique-5": { prompt: "Un contadino conta 10 teste e 32 zampe tra le sue galline e i suoi conigli. Quanti conigli ha?", options: ["4", "5", "6", "7"], explanation: "Con g galline e c conigli: g+c=10 e 2g+4c=32, il che dà c=6 e g=4." },
          "logique-6": { prompt: "Quale giorno viene dopo questa sequenza: martedì, giovedì, sabato, …?", options: ["Domenica", "Lunedì", "Martedì", "Mercoledì"], explanation: "La sequenza avanza di 2 giorni ogni volta: sabato + 2 giorni = lunedì." },
          "suite-1": { prompt: "Completa la sequenza: 2, 4, 8, 16, ?", options: ["24", "30", "32", "36"], explanation: "Ogni numero è moltiplicato per 2: 16 × 2 = 32." },
          "suite-2": { prompt: "Completa la sequenza: 1, 1, 2, 3, 5, 8, ?", options: ["11", "12", "13", "15"], explanation: "Sequenza di Fibonacci: ogni termine è la somma dei due precedenti. 5 + 8 = 13." },
          "suite-3": { prompt: "Completa la sequenza: 3, 6, 11, 18, 27, ?", options: ["36", "38", "40", "42"], explanation: "Gli intervalli aumentano di 2 in 2 (+3, +5, +7, +9, +11): 27 + 11 = 38." },
          "suite-4": { prompt: "Completa la sequenza: 1, 4, 9, 16, 25, ?", options: ["30", "34", "36", "42"], explanation: "Sono i quadrati successivi (1², 2², 3²...): 6² = 36." },
          "suite-5": { prompt: "Completa la sequenza: 2, 6, 18, 54, ?", options: ["108", "144", "162", "180"], explanation: "Ogni numero è moltiplicato per 3: 54 × 3 = 162." },
          "suite-6": { prompt: "Completa la sequenza: 1, 3, 6, 10, 15, ?", options: ["18", "20", "21", "24"], explanation: "Numeri triangolari: si aggiunge 2, poi 3, poi 4, poi 5, poi 6: 15 + 6 = 21." },
          "matrice-1": { prompt: "Completa la seguente matrice rispettando la logica delle righe e delle colonne.", options: ["● ● ●", "● ● ● ●", "● ● ● ● ●", "● ● ● ● ● ●"], explanation: "Il numero di punti di una cella = (numero di riga + numero di colonna − 1): 3 + 3 − 1 = 5." },
          "matrice-2": { prompt: "Completa la seguente matrice rispettando la logica delle righe e delle colonne.", options: ["△", "□", "○", "◇"], explanation: "Ogni riga è uno scorrimento circolare della precedente: la 3ª cella della riga 3 è □." },
          "matrice-3": { prompt: "Completa la seguente matrice rispettando la logica delle righe e delle colonne.", options: ["17", "18", "19", "20"], explanation: "I numeri aumentano di 2 leggendo la griglia riga per riga: 16 + 2 = 18." },
          "matrice-4": { prompt: "Completa la seguente matrice rispettando la logica delle righe e delle colonne.", options: ["7", "8", "9", "10"], explanation: "Ogni cella equivale al numero di riga moltiplicato per il numero di colonna: 3 × 3 = 9." },
          "matrice-5": { prompt: "Completa la seguente matrice rispettando la logica delle righe e delle colonne.", options: ["12", "14", "16", "18"], explanation: "Ogni cella raddoppia la precedente, sia sulle righe che sulle colonne: 8 × 2 = 16." },
          "matrice-6": { prompt: "Completa la seguente matrice rispettando la logica delle righe e delle colonne.", options: ["2", "3", "4", "5"], explanation: "Ogni riga diminuisce di 2 e inizia 1 in meno della precedente: 5 − 2 = 3." },
          "intrus-1": { prompt: "Trova l'intruso in questa lista: Cane, Gatto, Pesce, Tavolo.", options: ["Cane", "Gatto", "Pesce", "Tavolo"], explanation: "Cane, Gatto e Pesce sono animali; Tavolo è un oggetto, è l'intruso." },
          "intrus-2": { prompt: "Trova l'intruso in questa lista: Rosso, Blu, Verde, Lunedì.", options: ["Rosso", "Blu", "Verde", "Lunedì"], explanation: "Rosso, Blu e Verde sono colori; Lunedì è un giorno della settimana, è l'intruso." },
          "intrus-3": { prompt: "Trova l'intruso in questa lista: Mela, Banana, Carota, Pera.", options: ["Mela", "Banana", "Carota", "Pera"], explanation: "Mela, Banana e Pera sono frutti; Carota è un ortaggio, è l'intruso." },
          "intrus-4": { prompt: "Trova l'intruso in questa lista: Leone, Tigre, Aquila, Leopardo.", options: ["Leone", "Tigre", "Aquila", "Leopardo"], explanation: "Leone, Tigre e Leopardo sono felini; Aquila è un uccello, è l'intruso." },
          "intrus-5": { prompt: "Trova l'intruso in questa lista: Parigi, Londra, Tokyo, Europa.", options: ["Parigi", "Londra", "Tokyo", "Europa"], explanation: "Parigi, Londra e Tokyo sono città; Europa è un continente, è l'intruso." },
          "intrus-6": { prompt: "Trova l'intruso tra questi numeri: 4, 9, 16, 20.", options: ["4", "9", "16", "20"], explanation: "4, 9 e 16 sono quadrati perfetti (2², 3², 4²); 20 non lo è, è l'intruso." },
          "enigme-1": { prompt: "Quale simbolo completa la sequenza: ○ ● ○ ● ○ ?", options: ["○", "●", "◐", "◻"], explanation: "La sequenza alterna rigorosamente ○ e ●: dopo ○ viene sempre ●." },
          "enigme-2": { prompt: "Quale simbolo completa la sequenza: △ ▽ △ ▽ △ ?", options: ["△", "▽", "◇", "○"], explanation: "La sequenza alterna rigorosamente △ e ▽: dopo △ viene sempre ▽." },
          "enigme-3": { prompt: "Un triangolo è diviso in 4 piccoli triangoli uguali tracciando le sue tre mediane. Quanti triangoli si contano in totale (piccoli + grande combinati)?", options: ["4", "5", "6", "7"], explanation: "Si contano i 4 piccoli triangoli, più il grande triangolo originale: 4 + 1 = 5." },
          "enigme-4": { prompt: "Un orologio segna le 3:15. Qual è l'angolo approssimativo tra la lancetta delle ore e quella dei minuti?", options: ["0°", "7,5°", "15°", "30°"], explanation: "Alle 3:15, la lancetta delle ore è a 97,5° e quella dei minuti a 90°: la differenza è di circa 7,5°." },
          "enigme-5": { prompt: "Un cubo viene dipinto di rosso su tutte le facce e poi tagliato in 27 piccoli cubi identici (3×3×3). Quanti piccoli cubi non hanno ALCUNA faccia dipinta?", options: ["0", "1", "6", "8"], explanation: "Solo il piccolo cubo situato esattamente al centro non ha alcuna faccia dipinta: la risposta è 1." },
          "enigme-6": { prompt: "In una griglia quadrata di 3×3 caselle, quanti quadrati si contano in totale (di tutte le dimensioni)?", options: ["9", "12", "14", "16"], explanation: "9 quadrati di 1×1, 4 quadrati di 2×2 e 1 quadrato di 3×3: 9 + 4 + 1 = 14." },
        },
