        s8: { title: "8. Beveiliging", text: "We implementeren passende technische en organisatorische maatregelen om je gegevens te beschermen: versleuteling van communicatie (HTTPS), prioritaire lokale verwerking en beperkte toegang tot accountgegevens. Meer details op onze pagina {securite}." },
        s9: { title: "9. Wat we niet doen", text: "We verkopen je gegevens niet, tonen geen gerichte advertenties op basis van je persoonsgegevens, en bewaren je bestanden niet langer dan strikt noodzakelijk is om je te antwoorden." },
        s10: { title: "10. Wijzigingen in dit beleid", text: "Dit beleid kan worden bijgewerkt om wijzigingen in de Dienst of regelgeving te weerspiegelen. De datum van de laatste update staat bovenaan deze pagina." },
        supportLink: "Support",
        securiteLink: "Beveiliging",
