            "Güvenliği sağlamak ve kötüye kullanımı önlemek (kota sınırlaması, anormallik tespiti);",
            "Destek sayfası üzerinden taleplerinize yanıt vermek;",
            "Yapay zeka asistanının yanıt kalitesini, toplu ve tanımlayıcı olmayan bir şekilde iyileştirmek.",
