        s8: { title: "8. Güvenlik", text: "Verilerinizi korumak için uygun teknik ve organizasyonel önlemler uyguluyoruz: iletişimin şifrelenmesi (HTTPS), öncelikli yerel işleme ve hesap verilerine kısıtlı erişim. Daha fazla ayrıntı için {securite} sayfamıza bakın." },
        s9: { title: "9. Yapmadıklarımız", text: "Verilerinizi satmıyoruz, kişisel verilerinize dayalı hedefli reklam göstermiyoruz ve dosyalarınızı size yanıt vermek için kesinlikle gerekli olan süreden daha uzun tutmuyoruz." },
        s10: { title: "10. Bu politikadaki değişiklikler", text: "Bu politika, Hizmetteki veya mevzuattaki değişiklikleri yansıtmak üzere güncellenebilir. Son güncelleme tarihi bu sayfanın üst kısmında yer alır." },
