          "logique-3": { prompt: "Bugün çarşamba ise, 100 gün sonra hangi gün olacak?", options: ["Perşembe", "Cuma", "Cumartesi", "Pazar"], explanation: "100 = 14×7 + 2: döngüde 2 gün ileri gideriz, çarşamba + 2 = cuma." },
          "logique-4": { prompt: "Alice her zaman yalan söyler, Bob her zaman doğruyu söyler. Alice şöyle diyor: «Bob yalan söylüyor.» Buradan ne çıkarılabilir?", options: ["Bob doğruyu söylüyor", "Bob yalan söylüyor", "Alice doğruyu söylüyor", "Söylemek imkânsız"], explanation: "Alice her zaman yalan söyler, dolayısıyla «Bob yalan söylüyor» ifadesi yanlıştır: Bob doğruyu söylüyor." },
          "logique-5": { prompt: "Bir çiftçi tavukları ve tavşanları arasında 10 kafa ve 32 bacak sayıyor. Kaç tavşanı var?", options: ["4", "5", "6", "7"], explanation: "t tavuk ve r tavşan ile: t+r=10 ve 2t+4r=32, bu da r=6 ve t=4 verir." },
          "logique-6": { prompt: "Bu dizinin ardından hangi gün gelir: salı, perşembe, cumartesi, …?", options: ["Pazar", "Pazartesi", "Salı", "Çarşamba"], explanation: "Dizi her seferinde 2 gün ilerler: cumartesi + 2 gün = pazartesi." },
          "suite-1": { prompt: "Diziyi tamamlayın: 2, 4, 8, 16, ?", options: ["24", "30", "32", "36"], explanation: "Her sayı 2 ile çarpılır: 16 × 2 = 32." },
          "suite-2": { prompt: "Diziyi tamamlayın: 1, 1, 2, 3, 5, 8, ?", options: ["11", "12", "13", "15"], explanation: "Fibonacci dizisi: her terim önceki iki terimin toplamıdır. 5 + 8 = 13." },
          "suite-3": { prompt: "Diziyi tamamlayın: 3, 6, 11, 18, 27, ?", options: ["36", "38", "40", "42"], explanation: "Aralıklar her seferinde 2 artar (+3, +5, +7, +9, +11): 27 + 11 = 38." },
          "suite-4": { prompt: "Diziyi tamamlayın: 1, 4, 9, 16, 25, ?", options: ["30", "34", "36", "42"], explanation: "Bunlar ardışık karelerdir (1², 2², 3²...): 6² = 36." },
          "suite-5": { prompt: "Diziyi tamamlayın: 2, 6, 18, 54, ?", options: ["108", "144", "162", "180"], explanation: "Her sayı 3 ile çarpılır: 54 × 3 = 162." },
          "suite-6": { prompt: "Diziyi tamamlayın: 1, 3, 6, 10, 15, ?", options: ["18", "20", "21", "24"], explanation: "Üçgensel sayılar: 2, sonra 3, sonra 4, sonra 5, sonra 6 eklenir: 15 + 6 = 21." },
          "matrice-1": { prompt: "Aşağıdaki matrisi satır ve sütunlarının mantığına uyarak tamamlayın.", options: ["● ● ●", "● ● ● ●", "● ● ● ● ●", "● ● ● ● ● ●"], explanation: "Bir hücredeki nokta sayısı = (satır numarası + sütun numarası − 1): 3 + 3 − 1 = 5." },
          "matrice-2": { prompt: "Aşağıdaki matrisi satır ve sütunlarının mantığına uyarak tamamlayın.", options: ["△", "□", "○", "◇"], explanation: "Her satır bir öncekinin dairesel kaydırmasıdır: 3. satırın 3. hücresi □'dir." },
          "matrice-3": { prompt: "Aşağıdaki matrisi satır ve sütunlarının mantığına uyarak tamamlayın.", options: ["17", "18", "19", "20"], explanation: "Izgara satır satır okunduğunda sayılar 2 artar: 16 + 2 = 18." },
          "matrice-4": { prompt: "Aşağıdaki matrisi satır ve sütunlarının mantığına uyarak tamamlayın.", options: ["7", "8", "9", "10"], explanation: "Her hücre, satır numarasının sütun numarasıyla çarpımına eşittir: 3 × 3 = 9." },
          "matrice-5": { prompt: "Aşağıdaki matrisi satır ve sütunlarının mantığına uyarak tamamlayın.", options: ["12", "14", "16", "18"], explanation: "Her hücre, hem satırlarda hem sütunlarda bir öncekinin iki katıdır: 8 × 2 = 16." },
          "matrice-6": { prompt: "Aşağıdaki matrisi satır ve sütunlarının mantığına uyarak tamamlayın.", options: ["2", "3", "4", "5"], explanation: "Her satır 2 azalır ve bir öncekinden 1 az başlar: 5 − 2 = 3." },
          "intrus-1": { prompt: "Bu listede uyumsuz olanı bulun: Köpek, Kedi, Balık, Masa.", options: ["Köpek", "Kedi", "Balık", "Masa"], explanation: "Köpek, Kedi ve Balık hayvandır; Masa bir nesnedir, uyumsuz olan odur." },
