          "suite-3": { prompt: "补全数列：3、6、11、18、27、？", options: ["36", "38", "40", "42"], explanation: "差值每次增加2（+3、+5、+7、+9、+11）：27 + 11 = 38。" },
          "suite-4": { prompt: "补全数列：1、4、9、16、25、？", options: ["30", "34", "36", "42"], explanation: "这是连续的平方数（1²、2²、3²……）：6² = 36。" },
