          "logique-5": { prompt: "한 농부가 닭과 토끼를 세어보니 머리가 10개, 다리가 32개였다. 토끼는 몇 마리인가?", options: ["4", "5", "6", "7"], explanation: "닭 c마리, 토끼 r마리라 하면: c+r=10, 2c+4r=32 이므로 r=6, c=4." },
          "logique-6": { prompt: "이 수열 다음에 오는 요일은: 화요일, 목요일, 토요일, …?", options: ["일요일", "월요일", "화요일", "수요일"], explanation: "이 수열은 매번 2일씩 앞으로 나아간다: 토요일 + 2일 = 월요일." },
